import { Group, Mesh, PlaneGeometry, Color, DirectionalLight, DoubleSide, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, positionLocal, normalLocal, vec2, vec3, length as tslLength, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const colors = config.intent?.visualSpec?.colors ?? { ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10' };
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const root = new Group();
  const content = new Group();
  root.add(content);

  const geometries = [];
  const materials = [];
  const timelines = [];
  const disposableTextures = [];

  const rowWidth = 3.2;
  const rowHeight = 0.9;

  // -- drop-shadow plate behind row (soft radial falloff, engineered not blurred-css) --
  {
    const geo = new PlaneGeometry(rowWidth + 0.3, rowHeight + 0.3);
    geometries.push(geo);
    const mat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false, side: DoubleSide });
    const centered = uv().sub(vec2(0.5, 0.5));
    const dist = tslLength(centered);
    mat.colorNode = vec3(0.0, 0.0, 0.0);
    mat.opacityNode = smoothstep(0.5, 0.05, dist).mul(0.45);
    materials.push(mat);
    const shadow = new Mesh(geo, mat);
    shadow.position.set(0, 0, -0.08);
    content.add(shadow);
  }

  // -- machined-metal backing plate for the row --
  const backPlate = (() => {
    const geo = new PlaneGeometry(rowWidth, rowHeight);
    geometries.push(geo);
    const mat = new MeshStandardNodeMaterial({
      color: new Color(colors.ink),
      roughness: 0.58,
      metalness: 0.5,
      clearcoat: 0.15,
      side: DoubleSide
    });
    materials.push(mat);
    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, 0, -0.02);
    content.add(mesh);
    return mesh;
  })();

  // -- tessellated parallax thumbnail (displacement from depth map) --
  const thumbSize = 0.72;
  const thumbGeo = new PlaneGeometry(thumbSize, thumbSize, 64, 64);
  geometries.push(thumbGeo);
  const thumbMat = new MeshStandardNodeMaterial({
    color: new Color(0xffffff),
    roughness: 0.55,
    metalness: 0.35,
    side: DoubleSide
  });
  materials.push(thumbMat);
  const thumbMesh = new Mesh(thumbGeo, thumbMat);
  thumbMesh.position.set(-rowWidth / 2 + thumbSize / 2 + 0.22, 0, 0.03);
  content.add(thumbMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      thumbMat.colorNode = texture(tex, uv());
      disposableTextures.push(tex);
      thumbMat.needsUpdate = true;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      disposableTextures.push(tex);
      const depthSample = texture(tex, uv()).r;
      const displacement = depthSample.mul(float(0.06));
      thumbMat.positionNode = positionLocal.add(normalLocal.mul(displacement));
      thumbMat.needsUpdate = true;
    });
  }

  // -- subtle divider line --
  {
    const dividerGeo = new PlaneGeometry(rowWidth - 0.4, 0.006);
    geometries.push(dividerGeo);
    const dividerMat = new MeshBasicNodeMaterial({
      color: new Color(colors.accent),
      transparent: true,
      opacity: 0.32,
      side: DoubleSide
    });
    materials.push(dividerMat);
    const divider = new Mesh(dividerGeo, dividerMat);
    divider.position.set(0, -rowHeight / 2 + 0.06, 0.04);
    content.add(divider);
  }

  // -- title / meta text (only from spec copy, never invented) --
  const textOffsetX = -rowWidth / 2 + thumbSize + 0.5;
  let cursorY = 0.12;
  for (const item of items) {
    const role = item.role ?? 'body';
    const isTitle = role === 'title' || role === 'headline';
    const fontSize = item.typography?.fontSize ?? (isTitle ? 34 : 20);
    const textNode = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize,
      color: isTitle ? colors.paper : '#9aa1ad',
      align: 'left',
      maxWidthPx: 560
    });
    textNode.position.set(textOffsetX, cursorY, 0.05);
    content.add(textNode);
    cursorY -= isTitle ? 0.32 : 0.22;
  }

  // -- node-local rim light (accent hue, capped intensity) --
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.85);
  rimLight.position.set(-1.5, 0.6, 1.2);
  content.add(rimLight);

  // -- cinematic primitives (never inline the logic) --
  const primitiveResults = [];
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const p of primitiveConfigs) {
    const fn = ctx.primitives[p.name];
    if (typeof fn === 'function') {
      const target = p.name === 'parallax-scroll' || p.name === 'depth-rotate' ? content : root;
      const result = fn(target, { ...p.params, trigger: p.trigger });
      primitiveResults.push(result);
    }
  }
  const depthRotateResult = primitiveResults.find((r, i) => primitiveConfigs[i]?.name === 'depth-rotate');

  // -- idle breathing (single slow transform, <=2%) --
  const breatheTl = gsap.timeline({ repeat: -1, yoyo: true });
  breatheTl.to(content.scale, { x: 1.015, y: 1.015, z: 1.015, duration: 3.4, ease: 'sine.inOut' });
  timelines.push(breatheTl);

  // -- hover rise-in preset (subtle) --
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(content.position, { y: '+=0.15', duration: 0.5, ease: 'power2.out' });
  timelines.push(hoverTl);

  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(content.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)', yoyo: true, repeat: 1 });
  timelines.push(pressTl);

  root.userData.handlers = {
    onPointerEnter: () => {
      hoverTl.play();
      if (depthRotateResult?.timeline) depthRotateResult.timeline.play();
    },
    onPointerLeave: () => {
      hoverTl.reverse();
      if (depthRotateResult?.timeline) depthRotateResult.timeline.reverse();
    },
    onPointerDown: () => {
      pressTl.restart();
    },
    onClick: () => {
      ctx.emit('hub-pricing.select', { nodeId: config.id ?? 'pricing-row' });
    }
  };

  root.userData.cleanup = () => {
    for (const t of timelines) t.kill();
    for (const r of primitiveResults) {
      if (r && typeof r.cleanup === 'function') r.cleanup();
    }
    for (const g of geometries) g.dispose();
    for (const m of materials) m.dispose();
    for (const tex of disposableTextures) {
      if (tex && typeof tex.dispose === 'function') tex.dispose();
    }
  };

  return root;
}
